import json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
r=root/'runs/Fty2sz3dBwU.180s'
data={'report':json.loads((r/'out/report.json').read_text()),'units':json.loads((r/'units.json').read_text()),'events':[json.loads(l) for l in (r/'events.jsonl').read_text().splitlines()], 'langs':{l:json.loads((r/f'dub/{l}.json').read_text()) for l in ['en','ja','zh-Hans']}}
for u in data['units']: u.pop('voice',None)
html='''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VibeRick Dub — Studio concept</title>
<style>
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#17263a;background:#eef2f7;font-synthesis:none;--blue:#3269b7;--teal:#16766c;--violet:#7855ab}*{box-sizing:border-box}body{margin:0}button,select,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #cc7722;outline-offset:3px}button{border:1px solid #c7d1df;background:white;color:inherit;border-radius:7px;padding:9px 13px}button:hover{background:#e9eff7}button[aria-pressed="true"]{background:#17263a;color:white;border-color:#17263a}header{background:#17263a;color:white;padding:19px 32px;display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font-size:20px;letter-spacing:-.6px}.brand b{font-weight:450;color:#c2d0e1}.badge{padding:6px 11px;border:1px solid #71849b;border-radius:20px;font-size:12px}main{max-width:1540px;margin:auto;padding:25px 32px}.intro{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:19px}h1{font-size:clamp(23px,3vw,34px);letter-spacing:-1px;font-weight:650;margin:0 0 7px}p{line-height:1.5;margin:0;color:#58677a}.intro p{font-size:14px;max-width:780px}.tag{font-size:12px;color:#56667c;margin-bottom:8px}.workspace{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(310px,1fr);gap:18px}.monitor{background:#17263a;border-radius:11px;overflow:hidden}video{display:block;width:100%;aspect-ratio:16/9;background:#080d16}.transport{padding:12px 15px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;color:white}.transport button{background:#273b55;color:white;border-color:#52657c;font-size:13px}.transport button[aria-pressed="true"]{background:white;color:#17263a;border-color:white}.transport .time{margin-left:auto;font-variant-numeric:tabular-nums;font-size:13px}.media-note{color:#c4cede;font-size:12px;padding:0 16px 14px;line-height:1.45}.inspector{background:white;border:1px solid #d7dfeb;border-radius:11px;overflow:hidden;display:flex;flex-direction:column;min-height:450px}.panel-head{padding:15px 18px;border-bottom:1px solid #e1e6ef;display:flex;justify-content:space-between;align-items:center;gap:10px}.panel-head h2{font-size:17px;margin:0}.panel-head span{font-size:12px;color:#607189}.inspect-body{padding:17px 18px;overflow:auto;max-height:415px}.label{color:#607189;font-size:12px;margin:0 0 5px}.source{font-size:14px;line-height:1.5;color:#526174;margin-bottom:13px}.translation{font-size:18px;line-height:1.48;letter-spacing:-.2px;color:#17263a;margin-bottom:15px}.facts{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;padding:11px 0;border-top:1px solid #e5eaf1;border-bottom:1px solid #e5eaf1;margin-bottom:14px}.facts b{display:block;font-size:17px;font-weight:600;margin-top:3px}.history{list-style:none;padding:0;margin:9px 0}.history li{border-left:2px solid #dae2ee;padding:0 0 12px 12px;margin-left:4px;font-size:13px;line-height:1.4}.history li.fix{border-color:#bc7925}.history li.good{border-color:#2c867d}.history time{font-size:11px;color:#64748a;display:block;margin-bottom:3px}.inspect-body h3{font-size:13px;margin:0 0 10px}.timeline{background:white;border:1px solid #d7dfeb;border-radius:11px;margin-top:18px;padding:18px 20px}.timeline-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:8px}.timeline h2{font-size:17px;margin:0}.timeline-head p{font-size:12px}.legend{display:flex;gap:16px;font-size:12px;white-space:nowrap}.legend i{display:inline-block;width:9px;height:9px;background:#8593a6;border-radius:2px;margin-right:5px}.legend .fix{background:#b27625}.timeline-scroll{overflow-x:auto;padding:10px 0}.timeline-content{min-width:720px}.ruler{height:28px;margin-left:135px;position:relative;border-bottom:1px solid #dbe3ee}.ruler span{position:absolute;transform:translateX(-50%);font-size:11px;color:#67778d;font-variant-numeric:tabular-nums}.ruler span:first-child{transform:none}.ruler span:last-child{transform:translateX(-100%)}.lane{display:grid;grid-template-columns:135px 1fr;align-items:center;min-height:53px}.lane-label button{border:0;background:none;padding:7px 0;font-size:13px;text-align:left;font-weight:600}.lane-label button[aria-pressed="true"]{color:var(--blue)}.lane-label small{display:block;font-size:11px;color:#687a91;font-weight:400;margin-top:3px}.slots{height:38px;position:relative;background:repeating-linear-gradient(to right,#f5f7fb 0, #f5f7fb calc(16.666% - 1px),#e4eaf3 calc(16.666% - 1px),#e4eaf3 16.666%);border-bottom:1px solid #e7edf4}.slot{position:absolute;top:5px;height:28px;border:0;border-radius:3px;background:#ccd5e1;padding:0;overflow:hidden;color:#17263a;font-size:10px;min-width:3px}.slot.en{background:#c4d8f4}.slot.ja{background:#bfdfd9}.slot.zh-Hans{background:#dbcceb}.slot.repaired{box-shadow:inset 0 -4px #b27625}.slot.selected{outline:2px solid #17263a;outline-offset:1px;z-index:2}.slot:hover{filter:brightness(.94)}.playhead{position:absolute;top:0;bottom:0;width:2px;background:#17263a;pointer-events:none;z-index:3}.scrub{display:block;width:calc(100% - 135px);margin:10px 0 0 135px;accent-color:#3269b7}.timeline-foot{display:flex;justify-content:space-between;gap:20px;margin-top:13px;font-size:12px;color:#64748a}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.evidence,.replay{padding:20px;background:#fff;border:1px solid #d7dfeb;border-radius:11px}.bottom h2{font-size:17px;margin:0 0 13px}.evidence dl{display:grid;grid-template-columns:1fr auto;gap:10px;font-size:13px;margin:0}.evidence dt{color:#57677c}.evidence dd{margin:0;font-variant-numeric:tabular-nums}.evidence p{font-size:12px;margin-top:15px}.replay-tools{display:flex;gap:8px;align-items:center;margin-bottom:13px;flex-wrap:wrap}.replay-tools span{font-size:12px;color:#63748b;margin-left:auto}.progress-row{display:grid;grid-template-columns:70px 1fr 85px;align-items:center;gap:12px;font-size:12px;margin:9px 0}.progress-row progress{width:100%;accent-color:#3269b7}.progress-row:nth-of-type(2) progress{accent-color:#16766c}.progress-row:nth-of-type(3) progress{accent-color:#7855ab}.event-now{font-size:12px;color:#50627a;min-height:38px;line-height:1.45;margin-top:12px}.footnote{font-size:12px;margin:22px 0 5px;max-width:1050px;color:#607189}.error{color:#ffd6a7}.jump{font-size:13px;white-space:nowrap}@media(max-width:950px){main{padding:20px}.workspace{grid-template-columns:1fr}.inspect-body{max-height:350px}.inspector{min-height:0}.bottom{grid-template-columns:1fr}.intro{align-items:start}.intro .jump{white-space:normal}.timeline-head{align-items:start;flex-direction:column}.timeline-foot{display:block}.timeline-foot span{display:block;margin-bottom:5px}}@media(max-width:560px){header{padding:15px 18px;align-items:start}.badge{font-size:10px}main{padding:16px 12px}.intro{display:block}.jump{margin-top:12px}.timeline{padding:16px 12px}.transport .time{width:100%;margin-left:0}.intro h1{letter-spacing:-.6px}.facts{gap:12px}.legend{font-size:11px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style>
<header><div class="brand">VibeRick <b>Dub / Studio</b></div><span class="badge">Proposed interface · Recorded run</span></header>
<main><div class="intro"><div><h1>Hear every language. Inspect every decision.</h1><p>One Korean creator video, three dubbed tracks, one shared clock. Explore the real outputs and recorded agent decisions from a completed 3-minute run.</p></div><button class="jump" id="jump">Inspect a Japanese repair</button></div>
<div class="workspace"><section class="monitor" aria-label="Dub preview"><video id="video" controls playsinline preload="metadata"></video><div class="transport" id="transport"></div><p class="media-note" id="media-note">Published sample media. Switching languages keeps your position. Only the selected track plays.</p></section><aside class="inspector"><div class="panel-head"><h2>Segment inspector</h2><span id="segment-label"></span></div><div class="inspect-body" id="inspector"></div></aside></div>
<section class="timeline"><div class="timeline-head"><div><h2>One timeline, four listening perspectives</h2><p>Click a segment to seek and inspect it. Select a language to hear it.</p></div><div class="legend"><span><i></i>Source slot</span><span><i class="fix"></i>Agent repaired</span></div></div><div class="timeline-scroll"><div class="timeline-content"><div class="ruler" id="ruler"></div><div id="lanes"></div><label><span style="position:absolute;width:1px;height:1px;overflow:hidden">Seek video</span><input class="scrub" id="scrub" type="range" min="0" max="180" step="0.05" value="0"></label></div></div><div class="timeline-foot"><span>Bars repeat the recorded source slots for comparison. They are not waveforms or measured final dub placement.</span><span>23 source segments · 3:00</span></div></section>
<div class="bottom"><section class="replay"><h2>Watch the recorded repair process</h2><div class="replay-tools"><button id="replay-toggle">Replay events</button><button id="replay-reset">Reset</button><label>Speed <select id="speed"><option value="1">1×</option><option value="4">4×</option><option value="8" selected>8×</option></select></label><span id="event-clock">0:00 / 2:52</span></div><div id="progress"></div><p class="event-now" id="event-now">Replay the actual archived event sequence. This control does not start a new job.</p></section><section class="evidence"><h2>Evidence from this run</h2><dl><dt>Final automated listening verdicts</dt><dd>69 / 69 passed</dd><dt>Lines passing on the first check</dt><dd>66 / 69</dd><dt>Lines repaired before final pass</dt><dd>3</dd><dt>Recorded local processing time</dt><dd>2 min 52.3 sec</dd><dt>Largest per-language p95 lateness</dt><dd>0.16 sec</dd></dl><p>These are automated checks from one local run, not a human quality score, cloud latency benchmark, or proof of natural pauses. The public sample report matches this local report.</p></section></div>
<p class="footnote">Review prototype, 10 October 2026. Uses existing public sample videos and local run records. The proposed layout adds no generation, editing, or deployment capability. Event replay and media playback use separate clocks. A production studio would add measured audio waveforms, actual scene cuts, editable translations and before/after audio; those are not simulated here.</p></main>
<script id="run-data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById('run-data').textContent);const $=s=>document.querySelector(s);const names={orig:'Original · 한국어',en:'English',ja:'日本語','zh-Hans':'中文'};const base='https://storage.googleapis.com/viberick-dub-public/demo/Fty2sz3dBwU-180s/';let lang='en',selected=18,mediaVersion=0,desiredTime=0,desiredPlaying=false;const v=$('#video');const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const mm=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;const fixes=r=>r.actions.some(a=>['shorten','resynth','retranslate'].includes(a.do));
function transport(){ $('#transport').innerHTML=Object.entries(names).map(([k,n])=>`<button data-lang="${k}" aria-pressed="${lang===k}">${n}</button>`).join('')+'<span class="time" id="time">'+mm(desiredTime)+' / 3:00</span>';$('#transport').querySelectorAll('button').forEach(b=>b.onclick=()=>switchLang(b.dataset.lang)); }
async function play(){try{await v.play();}catch(x){$('#media-note').textContent='Track ready. Press Play to listen.';}}
function loadMedia(t,playing){const version=++mediaVersion;desiredTime=t;desiredPlaying=playing;v.src=base+'video.'+lang+'.mp4';v.onloadedmetadata=()=>{if(version!==mediaVersion)return;v.currentTime=Math.min(desiredTime,Math.max(0,v.duration-.1));if(desiredPlaying)play();};v.load();}
function switchLang(l){if(l===lang)return;const t=v.readyState>=1?v.currentTime:desiredTime;const playing=v.readyState>=1?!v.paused:desiredPlaying;lang=l;transport();drawLanes();inspect();loadMedia(t,playing);}
function seek(t){desiredTime=t;if(v.readyState>=1)v.currentTime=t;$('#scrub').value=t;position(t);}
function choose(i,l){selected=i;if(l!==lang)switchLang(l);seek(D.units[i].start);drawLanes();inspect();}
function drawLanes(){ $('#lanes').innerHTML=Object.entries(names).map(([l,n])=>`<div class="lane"><div class="lane-label"><button data-language="${l}" aria-pressed="${lang===l}">${n}<small>${l==='orig'?'Recorded source':D.langs[l].report.ok+'/23 checks passed'}</small></button></div><div class="slots">${D.units.map((u,i)=>{const r=l==='orig'?null:D.langs[l].rows[i];return `<button class="slot ${l} ${r&&fixes(r)?'repaired':''} ${selected===i&&lang===l?'selected':''}" style="left:${u.start/1.8}%;width:${Math.min(u.slot,180-u.start)/1.8}%" data-id="${i}" data-l="${l}" aria-label="${e(n)} segment ${i+1}, ${mm(u.start)}${r&&fixes(r)?', repaired':''}" title="${e(n)} · ${mm(u.start)} · segment ${i+1}">${u.slot>3?i+1:''}</button>`}).join('')}<div class="playhead"></div></div></div>`).join('');$('#lanes').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>choose(+b.dataset.id,b.dataset.l));$('#lanes').querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>switchLang(b.dataset.language));position(v.readyState>=1?v.currentTime:desiredTime);}
function action(ev){if(ev.do==='check')return ev.ok?'Listening check passed':`Listening check flagged: ${ev.issue||'needs review'}`;if(ev.do==='resynth')return 'Generated this line again';if(ev.do==='retranslate')return 'Re-translated: '+ev.text;if(ev.do==='shorten')return 'Shortened: '+ev.text;if(ev.do==='synth')return 'Generated audio'+(ev.dur?' · '+ev.dur+' sec':'');return ev.do||ev.kind;}
function inspect(){const u=D.units[selected];const r=lang==='orig'?null:D.langs[lang].rows[selected];$('#segment-label').textContent=`${selected+1} of 23 · ${mm(u.start)}`;const evs=D.events.filter(a=>a.kind==='line'&&a.lang===lang&&a.id===u.id);$('#inspector').innerHTML=`<p class="label">Korean source</p><p class="source">${e(u.text)}</p>${r?`<p class="label">${e(names[lang])} · final translation</p><p class="translation" lang="${lang}">${e(r.text)}</p><div class="facts"><span>Source slot<b>${r.slot.toFixed(2)} s</b></span><span>Recorded clip duration<b>${r.dur.toFixed(2)} s</b></span><span>Tempo factor<b>${r.tempo.toFixed(3)}×</b></span></div><h3>${fixes(r)?'A real repair, step by step':'Recorded line history'}</h3><ol class="history">${evs.map(a=>`<li class="${['resynth','retranslate','shorten'].includes(a.do)?'fix':a.do==='check'&&a.ok?'good':''}"><time>Run +${mm(a.t-D.events[0].t)}</time>${e(action(a))}</li>`).join('')}</ol>`:'<p class="translation">Select a dubbed language to inspect its translation and recorded checks.</p><div class="facts"><span>Source start<b>'+u.start.toFixed(2)+' s</b></span><span>Source end<b>'+u.end.toFixed(2)+' s</b></span><span>Allocated slot<b>'+u.slot.toFixed(2)+' s</b></span></div>'}`;}
function position(t){document.querySelectorAll('.playhead').forEach(x=>x.style.left=`${Math.min(t,180)/1.8}%`);if($('#time'))$('#time').textContent=mm(t)+' / 3:00';}
v.ontimeupdate=()=>{desiredTime=v.currentTime;$('#scrub').value=v.currentTime;position(v.currentTime)};v.onerror=()=>{$('#media-note').textContent='Public sample could not load. Check your connection, then select another track. Recorded evidence remains available below.';$('#media-note').classList.add('error');};v.oncanplay=()=>{$('#media-note').textContent='Published sample media. Switching languages keeps your position. Only the selected track plays.';$('#media-note').classList.remove('error')};$('#scrub').oninput=x=>seek(+x.target.value);$('#jump').onclick=()=>{choose(18,'ja');$('#inspector').scrollTop=0;};$('#ruler').innerHTML=[0,30,60,90,120,150,180].map(t=>`<span style="left:${t/1.8}%">${mm(t)}</span>`).join('');
let replayTime=0,replaying=false,lastFrame=null;const start=D.events[0].t;const end=D.report.sec_total;function replayDraw(){const es=D.events.filter(x=>x.t-start<=replayTime);$('#progress').innerHTML=Object.keys(D.langs).map(l=>{const checked=new Set(es.filter(x=>x.lang===l&&x.kind==='line'&&x.do==='check'&&x.ok).map(x=>x.id)).size;return `<div class="progress-row"><span>${e(names[l])}</span><progress max="23" value="${checked}" aria-label="${e(names[l])} lines passed"></progress><span>${checked} / 23 passed</span></div>`}).join('');$('#event-clock').textContent=mm(replayTime)+' / '+mm(end);const last=es.at(-1);$('#event-now').textContent=last?`${mm(last.t-start)} · ${last.lang?names[last.lang]+' · ':''}${last.kind==='line'?'Segment '+(last.id+1)+': '+action(last):({'start':'Source fetched','voice':'Voice routing recorded','separated':'Speech and music separated','transcribed':'Word timings transcribed','proofread':'Transcript proofread','brief':'Dubbing brief ready','cast':'Speaker voices assigned','translated':'Translation ready','voiced':'Initial speech generated','language_done':'Language mix completed','done':'Run completed'}[last.kind]||last.kind)}`:'Archived event replay ready. No new job will be created.';}
function frame(t){if(!replaying)return;if(lastFrame!==null)replayTime=Math.min(end,replayTime+(t-lastFrame)/1000*+$('#speed').value);lastFrame=t;replayDraw();if(replayTime>=end){replaying=false;$('#replay-toggle').textContent='Replay events';lastFrame=null}else requestAnimationFrame(frame);}
$('#replay-toggle').onclick=()=>{replaying=!replaying;if(replaying&&replayTime>=end)replayTime=0;lastFrame=null;$('#replay-toggle').textContent=replaying?'Pause replay':'Replay events';if(replaying)requestAnimationFrame(frame)};$('#replay-reset').onclick=()=>{replaying=false;replayTime=0;lastFrame=null;$('#replay-toggle').textContent='Replay events';replayDraw();};transport();drawLanes();inspect();replayDraw();loadMedia(0,false);
</script></html>'''
(root/'docs/review-2026-10-10/studio-concept.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
